public class Animal
{
    public string Name;
    public void Sleep() { Console.WriteLine("Sleeping"); }
}

// Dog inherits from Animal
public class Dog : Animal
{   // Dog gets Name field and Sleep() method
}

var d = new Dog();
d.Name = "Rex";
d.Sleep();

public class Vehicle  // base class
{
    public string Brand;
}

public class Car : Vehicle  // derived class
{
    public int Doors;
}

var car = new Car();
car.Brand = "Toyota";  // inherited
car.Doors = 4;         // own

public class Animal
{
    public string Name;
    public Animal(string name) { Name = name; }
}

public class Dog : Animal
{
    public string Breed;
    // Must call base(name) explicitly
    public Dog(string name, string breed) : base(name)
    {
        Breed = breed;
    }
}

var d = new Dog("Rex", "Labrador");

public class Animal
{
    public virtual void Speak() { Console.WriteLine("Animal"); }
}

public class Dog : Animal
{
    public override void Speak() { Console.WriteLine("Woof"); }
}

var a = new Dog();
a.Speak();  // prints 'Woof'

