public class Base
{
    public Base() { Console.WriteLine("Base ctor"); }
}

public class Derived : Base
{
    public Derived() { Console.WriteLine("Derived ctor"); }
}

var d = new Derived();

public sealed class DatabaseConnection
{
    public string ConnectionString;
    // Cannot be derived from - sealed
}

// This would NOT compile:
// public class MyConn : DatabaseConnection { }

public class Logger
{
    public virtual void Log() { }
}

public class FileLogger : Logger
{
    public sealed override void Log() { }
    // Cannot override Log() further
}

public class Animal
{
    public void PublicMethod() { }
    protected void ProtectedMethod() { }
    private void PrivateMethod() { }
}

public class Dog : Animal
{
    public void Test()
    {
        PublicMethod();     // OK
        ProtectedMethod();  // OK
        // PrivateMethod();  // ERROR!
    }
}

public class Point
{
    public int X, Y;
    public override string ToString()
    {
        return $"({X}, {Y})";
    }
}

var p = new Point { X = 3, Y = 4 };
Console.WriteLine(p.ToString());

